{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Inogatran, a peptidomimetic with a cyclohexylmethyl group, multiple amides and a free carboxylic acid, had oral bioavailability <5% in healthy volunteers; its polar, ionizable, peptide-like character supports low absorption for the similarly polar and acidic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Alvimopan, a larger amphiphilic molecule with a carboxylic acid and amide, has an absolute oral bioavailability of only about 6% in humans, showing that ionizable polar groups can dominate over lipophilic substituents and keep F below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tiopronin, a small N-acyl glycine with a free carboxylate, showed 63% absolute bioavailability in healthy subjects, but its much lower molecular weight and lack of the query's large polar barbiturate/cyclohexyl framework limit transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Perindopril has high oral bioavailability (66-95%), but this is largely attributable to its ester prodrug form and is not representative of the query's free carboxylic acid and highly polar imide-containing scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a highly polar, fully ionized carboxylic acid with a large barbiturate-like core and two cyclohexyl groups. Although several low-similarity analogues have high bioavailability, the most mechanistically relevant ionizable/peptidomimetic analogues (inogatran, alvimopan) show low oral bioavailability. The physicochemical prior of poor permeability and unfavorable absorption supports a low prediction, but transferability of the experimental evidence is limited by low Morgan similarity.",
  "evidence_gaps": [
    "No close structural analogues (Morgan similarity >0.3) with direct oral bioavailability data are available.",
    "No experimental data on active transport, efflux, or prodrug behavior for the barbiturate-glycine scaffold.",
    "Microdosing data (e.g., GPG-NH2) may not reflect therapeutic-dose absorption and are of limited transferability.",
    "The query's exact combination of a free carboxylate, three carbonyls, and two cyclohexyl groups is not represented by any single high-quality analogue."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

